class Item {
  constructor(title, label) {
    this.kind = "Item";
    this.title = title;
    this.label = label;
  }
}
class PinnedItem extends Item {
  constructor(title, label) {
    super(title, label);
    this.variant = "Pinned";
    this.sticky = true;
  }
}
exports.Item = Item;
exports.PinnedItem = PinnedItem;
exports.makeItem = (title, name) =>
  name === undefined ? new Item(title) : new PinnedItem(title, { name, revision: "1" });
